"""TP-C TOPIK I 읽기: second batch (v1.19, RYU 2026-11-25: about 30 questions per lesson page, 5 shown at a time).
Right answer written first; tools/topik_bank.py shuffles the choices (not ㉠㉡㉢㉣)."""
import random
from common import Q, SR, notice

def R(p, o, x):                     # one text, right answer first
    return Q(o, 0, x, p=p)

L = ["(가)", "(나)", "(다)", "(라)"]
def ORD(sents, x):                  # sents in the right order; labels and wrong orders are mixed with a fixed seed
    r = random.Random(sents[0]); lab = L[:]; r.shuffle(lab)        # lab[i] = label of sentence i
    p = "<br>".join(f"{l} {sents[lab.index(l)]}" for l in L)
    right = "-".join(lab); wrong = set()
    while len(wrong) < 3:
        w = lab[:]; r.shuffle(w)
        if w != lab and (len(wrong) < 1 or w[0] == lab[0] or r.random() < .5): wrong.add("-".join(w))
    return Q([right, *sorted(wrong)], 0, x, p=p)

def INS(text, box, pos, x1, same, x2):   # [보기] sentence: pos = 0..3 for ㉠..㉣; same = [right, ...]
    return SR([("[보기]의 문장이 들어갈 곳을 고르십시오.", ["㉠", "㉡", "㉢", "㉣"], pos, x1),
               ("윗글의 내용과 같은 것을 고르십시오.", same, 0, x2)], text + f"<br><br><b>[보기] {box}</b>")

def BL(text, blank, x1, same, x2):       # blank + content
    return SR([("(  )에 들어갈 알맞은 말을 고르십시오.", blank, 0, x1), ("윗글의 내용과 같은 것을 고르십시오.", same, 0, x2)], text)

def WHY(text, why, x1, same, x2):        # message: purpose + content
    return SR([("왜 이 글을 썼는지 고르십시오.", why, 0, x1), ("윗글의 내용과 같은 것을 고르십시오.", same, 0, x2)], text)

